@RestController
@RequestMapping("/api/webhooks")
public class WebhookController {

    private static final String SIGNATURE_HEADER = "X-Signature-256";
    private static final String SECRET = System.getenv("WEBHOOK_SECRET");

    @PostMapping("/stripe")
    public ResponseEntity<String> handleWebhook(
            @RequestHeader(value = SIGNATURE_HEADER, required = false) String signature,
            @RequestBody byte[] rawPayload) {

        if (signature == null || !verifySignature(rawPayload, signature)) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Invalid Signature");
        }

        // Proceed to process idempotent event downstream
        return ResponseEntity.ok("Received");
    }

    private boolean verifySignature(byte[] payload, String receivedSignature) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec secretKey = new SecretKeySpec(SECRET.getBytes(StandardCharsets.UTF_8), "HmacSHA256");
            mac.init(secretKey);
            byte[] computedHash = mac.doFinal(payload);

            String computedHex = HexFormat.of().formatHex(computedHash);
            return MessageDigest.isEqual(
                computedHex.getBytes(StandardCharsets.UTF_8),
                receivedSignature.getBytes(StandardCharsets.UTF_8)
            );
        } catch (Exception e) {
            return false;
        }
    }
}
